export function assertToolsCallTaskCapability(r,e,o){if(!r)throw new Error(`${o} does not support task creation (required for ${e})`);if("tools/call"===e&&!r.tools?.call)throw new Error(`${o} does not support task creation for tools/call (required for ${e})`)}export function assertClientRequestTaskCapability(r,e,o){if(!r)throw new Error(`${o} does not support task creation (required for ${e})`);switch(e){case"sampling/createMessage":if(!r.sampling?.createMessage)throw new Error(`${o} does not support task creation for sampling/createMessage (required for ${e})`);break;case"elicitation/create":if(!r.elicitation?.create)throw new Error(`${o} does not support task creation for elicitation/create (required for ${e})`)}}